/**
 * Comprehensive Automated Verification Suite for Leg-by-Leg Execution, Target Exit & Stop Loss Blueprints
 * 
 * Verifies:
 * 1. Every strategy leg generated by strategyEngine has role, entryPrice, entryRule, targetPrice, targetRule, stopLossPrice, stopLossRule, and spotTrigger.
 * 2. Angel One (ANGELONE) Iron Condor user exact scenario:
 *    - BUY ₹250 PUT @ ₹0.057 (Downside Wing / Margin Reducer)
 *    - SELL ₹300 PUT @ ₹1.961 (Short Put / Theta Decay Harvester)
 *    - SELL ₹400 CALL @ ₹7.414 (Short Call / Theta Decay Harvester)
 *    - BUY ₹450 CALL @ ₹1.47 (Upside Wing / Margin Reducer)
 * 3. Bull Put Spread & Bear Call Spread credit leg targets (50% decay) and stop loss (2.5x credit stop).
 * 4. Bull Call Spread & Bear Put Spread debit spread leg rules.
 * 5. Outright Long Call & Long Put momentum leg targets (+55%) and stop loss (-40%).
 * 6. UI Table & Card view rendering of Leg-by-Leg Execution Blueprint.
 */

import assert from 'assert';
import { scanStrategiesForAsset, enrichLegsWithExecutionPlan, STRATEGY_CATEGORIES } from './src/quant/strategyEngine.js';
import { renderScannerTable, renderScannerCards } from './src/components/scannerView.js';

console.log('🧪 Starting Leg-by-Leg Entry, Target Exit & Stop Loss Verification Suite...\n');

// Mock DOM environment for UI rendering tests
const mockElements = new Map();
global.document = {
  getElementById: (id) => {
    if (!mockElements.has(id)) {
      mockElements.set(id, {
        innerHTML: '',
        dataset: {},
        classList: {
          contains: () => false,
          add: () => {},
          remove: () => {},
          toggle: () => {}
        },
        querySelectorAll: () => []
      });
    }
    return mockElements.get(id);
  }
};
global.window = { refreshIcons: () => {} };

// ----------------------------------------------------------------------------
// Test 1: User's Exact ANGELONE Iron Condor Execution Blueprint
// ----------------------------------------------------------------------------
console.log('▶ Test 1: Verifying User Exact Scenario: ANGELONE Iron Condor (4 Legs)...');

const angelOneLegs = [
  { type: 'put', action: 'buy', strike: 250, premium: 0.057, contracts: 1, label: 'Buy ₹250 Put' },
  { type: 'put', action: 'sell', strike: 300, premium: 1.961, contracts: 1, label: 'Sell ₹300 Put' },
  { type: 'call', action: 'sell', strike: 400, premium: 7.414, contracts: 1, label: 'Sell ₹400 Call' },
  { type: 'call', action: 'buy', strike: 450, premium: 1.47, contracts: 1, label: 'Buy ₹450 Call' }
];

enrichLegsWithExecutionPlan(angelOneLegs, {
  category: STRATEGY_CATEGORIES.IRON_CONDORS,
  strategyName: 'Iron Condor (Delta-Neutral)',
  S: 359.15,
  lotSize: 200,
  curr: '₹',
  isCredit: true,
  market: 'IN'
});

const putWing = angelOneLegs.find(l => l.strike === 250);
const shortPut = angelOneLegs.find(l => l.strike === 300);
const shortCall = angelOneLegs.find(l => l.strike === 400);
const callWing = angelOneLegs.find(l => l.strike === 450);

// Assert Leg 1: BUY ₹250 PUT
assert(putWing, '250 Put Wing must exist');
assert.strictEqual(putWing.action, 'buy');
assert.strictEqual(putWing.entryPrice, 0.057);
assert(putWing.role.includes('Downside Protective Wing'), 'Role must reflect Downside Protective Wing');
assert(putWing.entryRule.includes('Buy 1st'), 'Entry rule must instruct buying wing 1st for margin relief');
assert.strictEqual(putWing.stopLossPrice, 0.057, 'Long wing stop loss is strictly capped at entry premium (defined risk)');
assert(putWing.stopLossRule.includes('Defined Risk Wing'), 'Stop loss rule must describe defined risk');
assert(putWing.targetRule.includes('Close simultaneously'), 'Target rule must specify closing with short leg');

// Assert Leg 2: SELL ₹300 PUT
assert(shortPut, '300 Short Put must exist');
assert.strictEqual(shortPut.action, 'sell');
assert.strictEqual(shortPut.entryPrice, 1.961);
assert(shortPut.role.includes('Short Put'), 'Role must identify Short Put');
assert(shortPut.entryRule.includes('Sell 2nd'), 'Entry rule must instruct selling after protective wing');
assert.strictEqual(shortPut.targetPrice, 0.981, 'Short put target exit must be 50% credit buyback');
assert.strictEqual(shortPut.stopLossPrice, 4.902, 'Short put stop loss must be 2.5x entry credit stop');
assert(shortPut.stopLossRule.includes('2.5x credit stop'), 'Stop rule must state 2.5x credit stop');
assert(shortPut.spotTrigger.includes('300'), 'Spot trigger must monitor strike test at 300');

// Assert Leg 3: SELL ₹400 CALL
assert(shortCall, '400 Short Call must exist');
assert.strictEqual(shortCall.action, 'sell');
assert.strictEqual(shortCall.entryPrice, 7.414);
assert(shortCall.role.includes('Short Call'), 'Role must identify Short Call');
assert.strictEqual(shortCall.targetPrice, 3.707, 'Short call target exit must be 50% credit buyback');
assert.strictEqual(shortCall.stopLossPrice, 18.535, 'Short call stop loss must be 2.5x entry credit stop');
assert(shortCall.spotTrigger.includes('400'), 'Spot trigger must monitor strike test at 400');

// Assert Leg 4: BUY ₹450 CALL
assert(callWing, '450 Call Wing must exist');
assert.strictEqual(callWing.action, 'buy');
assert.strictEqual(callWing.entryPrice, 1.47);
assert(callWing.role.includes('Upside Protective Wing'), 'Role must reflect Upside Protective Wing');
assert.strictEqual(callWing.stopLossPrice, 1.47, 'Call wing stop loss is capped at entry premium');

console.log('  ✅ ANGELONE Iron Condor all 4 legs verified with exact institutional rules:');
angelOneLegs.forEach((l, i) => {
  console.log(`     [Leg ${i+1}] ${l.action.toUpperCase()} ₹${l.strike} ${l.type.toUpperCase()} @ ₹${l.entryPrice}`);
  console.log(`            Role: ${l.role}`);
  console.log(`            Entry: ${l.entryRule}`);
  console.log(`            Target (TP): ₹${l.targetPrice} (${l.targetRule})`);
  console.log(`            Stop Loss (SL): ₹${l.stopLossPrice} (${l.stopLossRule})`);
  console.log(`            Trigger: ${l.spotTrigger}`);
});

// ----------------------------------------------------------------------------
// Test 2: Full Asset Scan Attaches Granular Leg Plans Across All Categories
// ----------------------------------------------------------------------------
console.log('\n▶ Test 2: Verifying scanStrategiesForAsset automatically enriches all strategy legs...');

const sampleQuote = {
  ticker: 'RELIANCE.NS',
  displayTicker: 'RELIANCE',
  name: 'Reliance Industries Ltd',
  market: 'IN',
  type: 'STOCK',
  price: 2500,
  strikeStep: 20,
  iv: 28.0,
  hv: 22.0, // VRP = +6.0% (rich vol)
  ivRank: 60,
  sma50: 2400, // Uptrend
  currency: 'INR',
  currencySymbol: '₹',
  lotSize: 250
};

const strats = scanStrategiesForAsset(sampleQuote);
assert(strats.length > 0, 'Must generate strategies for rich vol quote');

strats.forEach(strat => {
  assert(Array.isArray(strat.legs) && strat.legs.length > 0, `${strat.strategyName} must have legs`);
  strat.legs.forEach(leg => {
    assert(leg.role, `${strat.strategyName} leg must have role`);
    assert(typeof leg.entryPrice === 'number', `${strat.strategyName} leg must have entryPrice`);
    assert(leg.entryRule, `${strat.strategyName} leg must have entryRule`);
    assert(typeof leg.targetPrice === 'number', `${strat.strategyName} leg must have targetPrice`);
    assert(leg.targetRule, `${strat.strategyName} leg must have targetRule`);
    assert(typeof leg.stopLossPrice === 'number', `${strat.strategyName} leg must have stopLossPrice`);
    assert(leg.stopLossRule, `${strat.strategyName} leg must have stopLossRule`);
    assert(leg.spotTrigger, `${strat.strategyName} leg must have spotTrigger`);
  });
});
console.log(`  ✅ All ${strats.length} generated strategies have 100% enriched legs.`);

// ----------------------------------------------------------------------------
// Test 3: Verifying UI Tabular View & Card View Leg-by-Leg Rendering
// ----------------------------------------------------------------------------
console.log('\n▶ Test 3: Verifying UI Tabular & Card View HTML rendering of Leg Execution Matrix...');

renderScannerTable('testContainer', strats.slice(0, 3));
const tableOutput = mockElements.get('testContainer').innerHTML;

assert(tableOutput.includes('detail-col-legs-blueprint'), 'Detail drawer must contain detail-col-legs-blueprint');
assert(tableOutput.includes('legs-blueprint-table'), 'Detail drawer must contain legs-blueprint-table');
assert(tableOutput.includes('Leg-by-Leg Execution Blueprint, Targets &amp; Stop Loss'), 'Detail drawer must have title');
assert(tableOutput.includes('leg-pill-tp'), 'Leg pill must render mini target exit badge');
assert(tableOutput.includes('leg-pill-sl'), 'Leg pill must render mini stop loss badge');
console.log('  ✅ Table View drawer and leg pills correctly display Leg Execution Blueprint & SL matrix.');

renderScannerCards('testContainer', strats.slice(0, 3));
const cardsOutput = mockElements.get('testContainer').innerHTML;

assert(cardsOutput.includes('card-legs-blueprint'), 'Card must contain card-legs-blueprint');
assert(cardsOutput.includes('card-leg-blueprint-item'), 'Card must contain card-leg-blueprint-item');
assert(cardsOutput.includes('Leg-by-Leg Execution &amp; SL Matrix:'), 'Card must render blueprint section header');
console.log('  ✅ Cards View correctly renders Leg Execution & Stop Loss Matrix.');

console.log('\n🎉 ALL LEG-BY-LEG ENTRY, TARGET EXIT & STOP LOSS TESTS PASSED SUCCESSFULLY!');
